from PIL import Image
import numpy as np
im=np.array(Image.open('mol_0056.png').convert('L'))<128
sub=im[110:280,300:460]
from collections import deque
lab=-np.ones(sub.shape,int); n=0
for i in range(sub.shape[0]):
  for j in range(sub.shape[1]):
    if sub[i,j] and lab[i,j]<0:
      q=deque([(i,j)]); lab[i,j]=n; pts=[]
      while q:
        a,b=q.popleft(); pts.append((a,b))
        for da in(-1,0,1):
          for db in(-1,0,1):
            x,y=a+da,b+db
            if 0<=x<sub.shape[0] and 0<=y<sub.shape[1] and sub[x,y] and lab[x,y]<0:
              lab[x,y]=n; q.append((x,y))
      pts=np.array(pts,float)
      if len(pts)<400:
        c=pts.mean(0); p=pts-c
        u,s,vt=np.linalg.svd(p,0)
        print(n, len(pts), 'center y,x=',(c[0]+110, c[1]+300), 'principal dir (dy,dx)=',vt[0], 'len', s[0]/len(pts)**.5*2)
      n+=1
"

